<script src="https://unpkg.com/lucide@0.468.0/dist/umd/lucide.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{if(window.lucide)lucide.createIcons();document.getElementById('adminMenuToggle')?.addEventListener('click',()=>document.getElementById('adminSidebar').classList.toggle('open'));const openModal=id=>{const modal=document.getElementById(id);if(!modal)return;modal.classList.add('open');modal.querySelector('input, textarea, select, button')?.focus();};const closeModal=modal=>modal?.classList.remove('open');document.querySelectorAll('[data-open-modal]').forEach(el=>el.addEventListener('click',()=>openModal(el.dataset.openModal)));document.querySelectorAll('[data-close-modal]').forEach(el=>el.addEventListener('click',()=>closeModal(el.closest('.admin-modal'))));document.querySelectorAll('.admin-modal').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)closeModal(modal);}));document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.admin-modal.open').forEach(closeModal);});});</script>@stack('scripts')</body></html>
